create table if not exists v2_mt5_bridges (id text primary key, customer_id text not null, executor_id text not null, machine_id text not null, status text not null, version text not null, created_at timestamptz default now());
create table if not exists v2_mt5_agents (id text primary key, bridge_id text not null references v2_mt5_bridges(id), version text not null, capabilities jsonb not null default '[]');
create table if not exists v2_mt5_terminals (id text primary key, bridge_id text not null, server text, status text not null, last_heartbeat_at timestamptz);
create table if not exists v2_mt5_accounts (id text primary key, customer_id text not null, executor_id text not null, bridge_id text not null, login text not null, server text not null, environment text not null, credential_ref text not null, investor_credential_ref text, metadata jsonb not null default '{}');
create table if not exists v2_mt5_versions (id text primary key, component text not null, version text not null, required boolean default false);
create table if not exists v2_mt5_runtime (id text primary key, bridge_id text not null, account_id text, state jsonb not null default '{}', updated_at timestamptz default now());
create table if not exists v2_mt5_sync (id text primary key, bridge_id text not null, account_id text, sync_type text not null, status text not null, payload jsonb not null default '{}', updated_at timestamptz default now());
create table if not exists v2_mt5_health (id text primary key, bridge_id text not null, account_id text, status text not null, latency_ms integer not null default 0, reconnect_count integer not null default 0, offline_duration_ms integer not null default 0, version text, recorded_at timestamptz default now());
create table if not exists v2_mt5_recovery (id text primary key, bridge_id text not null, account_id text, reason text not null, status text not null, actions jsonb not null default '[]', created_at timestamptz default now());
create table if not exists v2_bridge_events (id text primary key, bridge_id text not null, customer_id text not null, event_type text not null, severity text not null, payload jsonb not null default '{}', created_at timestamptz default now());
create table if not exists v2_bridge_logs (id text primary key, bridge_id text not null, level text not null, message text not null, payload jsonb not null default '{}', created_at timestamptz default now());
alter table v2_mt5_bridges enable row level security;
alter table v2_mt5_agents enable row level security;
alter table v2_mt5_terminals enable row level security;
alter table v2_mt5_accounts enable row level security;
alter table v2_mt5_versions enable row level security;
alter table v2_mt5_runtime enable row level security;
alter table v2_mt5_sync enable row level security;
alter table v2_mt5_health enable row level security;
alter table v2_mt5_recovery enable row level security;
alter table v2_bridge_events enable row level security;
alter table v2_bridge_logs enable row level security;
